style.css:
@-moz-document domain("google.com") {
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: -1;
    background: linear-gradient(135deg, #6ec6ff 25%, #ffffff 25%, #ffffff 50%, #6ec6ff 50%, #6ec6ff 75%, #ffffff 75%, #ffffff 100%);
    background-size: 200px 200px;
    animation: wavey 5s linear infinite;
    opacity: 0.8;
  }

  @keyframes wavey {
    0% {
      background-position: 0 0;
    }
    100% {
      background-position: 200px 200px;
    }
  }

  /* Optional: Hide Google background or make content cleaner */
  body {
    background: transparent !important;
  }
}
